{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 public access is not explicitly blocked",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "The admin dashboard bucket has no public access block configuration. A future ACL or bucket policy change could unintentionally expose its contents publicly."
    },
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 bucket encryption is not explicitly configured",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The bucket does not declare server-side encryption in Terraform, leaving encryption behavior dependent on external service or account defaults."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "Without versioning, dashboard objects cannot be reliably recovered after accidental deletion, overwrite, or malicious modification."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is not enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The bucket does not record server access requests, reducing visibility into unauthorized or suspicious access to dashboard assets."
    },
    {
      "check_id": "CKV_AWS_70",
      "title": "Unencrypted transport is not denied",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "No bucket policy denies requests made without TLS, so clients may access bucket data over unencrypted HTTP."
    }
  ],
  "patched_code": "data "aws_caller_identity" "current" {}

resource "aws_s3_bucket" "admin_dashboard" {
  bucket = "smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.admin_dashboard.arn,
          "${aws_s3_bucket.admin_dashboard.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "admin_dashboard_access_logs" {
  bucket = "scpm-admin-dashboard-access-logs-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "admin_dashboard_access_logs" {
  bucket = aws_s3_bucket.admin_dashboard_access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "admin_dashboard_access_logs" {
  bucket = aws_s3_bucket.admin_dashboard_access_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "admin_dashboard_access_logs" {
  bucket = aws_s3_bucket.admin_dashboard_access_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "admin_dashboard_access_logs" {
  bucket = aws_s3_bucket.admin_dashboard_access_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.admin_dashboard_access_logs.arn,
          "${aws_s3_bucket.admin_dashboard_access_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid    = "AllowS3ServerAccessLogs"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.admin_dashboard_access_logs.arn}/admin-dashboard-access/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.admin_dashboard.arn
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "admin_dashboard" {
  bucket        = aws_s3_bucket.admin_dashboard.id
  target_bucket = aws_s3_bucket.admin_dashboard_access_logs.id
  target_prefix = "admin-dashboard-access/"

  depends_on = [aws_s3_bucket_policy.admin_dashboard_access_logs]
}
",
  "fix_summary": "Added explicit public access blocking, server-side encryption, versioning, TLS-only bucket policies, and S3 server access logging. A dedicated encrypted, versioned, private log bucket was added with a narrowly scoped log-delivery policy."
}
